const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Windhoek geometry
  const windhoek = ee.Geometry.Point([17.08, -22.56]);
  const buffer = windhoek.buffer(5000); // 5km buffer for region

  // 2. Function to mask clouds using SCL band
  function maskClouds(img) {
    const scl = img.select('SCL');
    const cloud = scl.eq(3).or(scl.eq(8)).or(scl.eq(9)); // Cloud/cirrus classes
    return img.updateMask(cloud.not());
  }

  // 3. Get Sentinel-2 data for both dates
  const col2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer)
    .filterDate('2020-01-25', '2020-02-02')
    .map(maskClouds)
    .select(['B4', 'B8']); // Red, NIR for NDVI

  const col2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer)
    .filterDate('2021-02-04', '2021-02-10')
    .map(maskClouds)
    .select(['B4', 'B8']);

  const size2020 = col2020.size().getInfo();
  const size2021 = col2021.size().getInfo();

  print(`2020-01-29 Images: ${size2020}`);
  print(`2021-02-07 Images: ${size2021}`);

  // Check for empty collections
  if (size2020 === 0 || size2021 === 0) {
    print(`No data found for one or both dates.`);
    print(`<answer>C1</answer>`);
    return;
  }

  // 4. Calculate median NDVI for each date
  const img2020 = col2020.median();
  const img2021 = col2021.median();

  // Calculate NDVI: (NIR - Red) / (NIR + Red)
  const ndvi2020 = img2020.normalizedDifference(['B8', 'B4']).rename('NDVI');
  const ndvi2021 = img2021.normalizedDifference(['B8', 'B4']).rename('NDVI');

  // 5. Calculate valid pixel count and NDVI values
  const stats2020 = ndvi2020.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const ndvi_val_2020 = stats2020.NDVI_mean;
  const ndvi_val_2021 = stats2021.NDVI_mean;
  const count_2020 = stats2020.NDVI_count;
  const count_2021 = stats2021.NDVI_count;

  print(`2020-01-29: NDVI=${ndvi_val_2020?.toFixed(3)}, Pixels=${count_2020}`);
  print(`2021-02-07: NDVI=${ndvi_val_2021?.toFixed(3)}, Pixels=${count_2021}`);

  // Check for valid pixels
  if (count_2020 === 0 || count_2021 === 0) {
    print(`No valid pixels after masking.`);
    print(`<answer>C2</answer>`);
    return;
  }

  // Check for valid NDVI values
  if (ndvi_val_2020 === null || ndvi_val_2020 === undefined || 
      ndvi_val_2021 === null || ndvi_val_2021 === undefined ||
      isNaN(ndvi_val_2020) || isNaN(ndvi_val_2021) ||
      ndvi_val_2020 < -1 || ndvi_val_2020 > 1 ||
      ndvi_val_2021 < -1 || ndvi_val_2021 > 1) {
    print(`Invalid NDVI calculation.`);
    print(`<answer>C3</answer>`);
    return;
  }

  // 6. Compare NDVI values
  print(`NDVI Change: ${(ndvi_val_2021 - ndvi_val_2020).toFixed(3)}`);

  if (ndvi_val_2021 > ndvi_val_2020) {
    print(`<answer>A</answer>`);
  } else {
    print(`<answer>B</answer>`);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
